1	import { existsSync, mkdirSync, readFileSync } from "node:fs";
2	import { join, resolve } from "node:path";
3	import type {
4	  BlockagesAddParams,
5	  BlockagesAddResult,
6	  BlockagesDeleteParams,
7	  BlockagesDeleteResult,
8	  BlockagesListResult,
9	  BlockagesResolveParams,
10	  BlockagesResolveResult,
11	  CommentAddParams,
12	  CommentAddResult,
13	  CommentDeleteParams,
14	  CommentDeleteResult,
15	  CommentsListResult,
16	  CommentUpdateParams,
17	  CommentUpdateResult,
18	  ConfigFile,
19	  CreateParams,
20	  CreateResult,
21	  DependenciesFile,
22	  Event,
23	  HistoryResult,
24	  IndexEntry,
25	  IndexFile,
26	  InitResult,
27	  IssueId,
28	  IssueProperties,
29	  IssueStatus,
30	  ListParams,
31	  ListResult,
32	  NextResult,
33	  UpdateParams,
34	  UpdateResult,
35	  UserEntry,
36	  UsersFile,
37	  UsersListResult,
38	  UsersRegenerateResult,
39	  UsersRegisterResult,
40	  UsersRevokeResult,
41	  ViewResult,
42	} from "../types";
43	import { resolveAuthor } from "./auth";
44	import { ErrorCodes, AgentrackError } from "./errors";
45	import { appendEvent, computeComments, computeState, replayEvents } from "./events";
46	import { atomicWriteJSON, readJSON } from "./file-io";
47	import { generateCommentId, generateId } from "./id";
48	import {
49	  addChild,
50	  findEntry,
51	  getChildren,
52	  insertEntry,
53	  readIndex,
54	  removeChild,
55	  updateEntry,
56	  writeIndex,
57	} from "./index-manager";
58	import { resolveTrackerDir } from "./resolution";
59	import {
60	  addBlockage,
61	  deleteBlockage,
62	  detectCycle,
63	  getImpactScore,
64	  readDependencies,
65	  resolveBlockage,
66	  writeDependencies,
67	} from "./dependency-manager";
68	import {
69	  computeUpwardPromotions,
70	  isStatusAfter,
71	  validateNewChild,
72	  validateParentStatusChange,
73	} from "./hierarchy";
74	
75	const AGENTACK_DIR = ".agentrack";
76	
77	/**
78	 * Read dependencies.json synchronously (used inside sort comparator).
79	 */
80	function readDependenciesSync(trackerDir: string): DependenciesFile {
81	  const contents = readFileSync(join(trackerDir, "dependencies.json"), "utf-8");
82	  return JSON.parse(contents) as DependenciesFile;
83	}
84	
85	/**
86	 * Default config.json contents.
87	 */
88	const DEFAULT_CONFIG: ConfigFile = {
89	  auth: {
90	    mode: "open",
91	    defaultUser: "anonymous",
92	  },
93	};
94	
95	/**
96	 * Default index.json contents.
97	 */
98	const DEFAULT_INDEX: IndexFile = {
99	  open: [],
100	  closed: [],
101	  childrenOf: {},
102	};
103	
104	/**
105	 * Default dependencies.json contents.
106	 */
107	const DEFAULT_DEPENDENCIES: DependenciesFile = {
108	  blockedBy: {},
109	  blocks: {},
110	};
111	
112	/**
113	 * Default users.json contents.
114	 */
115	const DEFAULT_USERS: UsersFile = {
116	  users: [],
117	};
118	
119	/**
120	 * Generate a token: tk_ + 8 random alphanumeric characters.
121	 */
122	function generateToken(): string {
123	  return `tk_${Math.random().toString(36).slice(2, 10)}`;
124	}
125	
126	/**
127	 * Recursively auto-close done children when a parent is closed.
128	 * Appends system-authored events to each child's issue file and updates the index.
129	 * Returns the updated index.
130	 */
131	async function cascadeClose(
132	  index: IndexFile,
133	  issueId: IssueId,
134	  trackerDir: string,
135	): Promise<IndexFile> {
136	  const childIds = getChildren(index, issueId);
137	  let currentIndex = index;
138	
139	  for (const childId of childIds) {
140	    const childEntry = findEntry(currentIndex, childId);
141	    if (!childEntry || childEntry.status !== "done") continue;
142	
143	    const now = new Date().toISOString();
144	    const event: Event = {
145	      type: "update",
146	      timestamp: now,
147	      author: "system",
148	      content: {
149	        status: "closed",
150	        reason: "auto-closed: parent closed",
151	      },
152	    };
153	
154	    const childPath = join(trackerDir, childEntry.path);
155	    await appendEvent(childPath, event);
156	
157	    currentIndex = updateEntry(currentIndex, childId, { status: "closed" });
158	
159	    // Recursively cascade to the child's own children
160	    currentIndex = await cascadeClose(currentIndex, childId, trackerDir);
161	  }
162	
163	  return currentIndex;
164	}
165	
166	/**
167	 * Tracker — the main programmatic API for agentrack.
168	 *
169	 * Provides methods for issue CRUD, comments, blockages, user management,
170	 * and event history. The constructor accepts a `cwd` parameter that defaults
171	 * to `process.cwd()`. It does NOT validate that `.agentrack/` exists at
172	 * construction time — resolution happens on each method call.
173	 *
174	 * @example
175	 * ```typescript
176	 * import { Tracker } from "agentrack";
177	 *
178	 * const tracker = new Tracker("/path/to/project");
179	 * await tracker.init();
180	 * const { id } = await tracker.create({ title: "My first issue" });
181	 * ```
182	 */
183	export class Tracker {
184	  private cwd: string;
185	
186	  /**
187	   * Create a new Tracker instance.
188	   *
189	   * @param cwd - Working directory to resolve `.agentrack/` from. Defaults to `process.cwd()`.
190	   */
191	  constructor(cwd?: string) {
192	    this.cwd = cwd ?? process.cwd();
193	  }
194	
195	  /**
196	   * Initialize a new `.agentrack/` directory in `cwd`.
197	   *
198	   * Creates the directory structure with all initial files:
199	   * `config.json`, `index.json`, `dependencies.json`, `users.json`,
200	   * and an empty `issues/` subdirectory.
201	   *
202	   * @returns `{ result: "OK", path }` on success, or `{ result: "ALREADY_INITIALIZED", path }` if already exists
203	   *
204	   * @example
205	   * ```typescript
206	   * const result = await tracker.init();
207	   * if (result.result === "OK") console.log("Created at", result.path);
208	   * ```
209	   */
210	  async init(): Promise<InitResult> {
211	    const trackerDir = join(this.cwd, AGENTACK_DIR);
212	
213	    if (existsSync(trackerDir)) {
214	      return { result: "ALREADY_INITIALIZED", path: resolve(trackerDir) };
215	    }
216	
217	    mkdirSync(trackerDir, { recursive: true });
218	    mkdirSync(join(trackerDir, "issues"), { recursive: true });
219	
220	    await atomicWriteJSON(join(trackerDir, "config.json"), DEFAULT_CONFIG);
221	    await atomicWriteJSON(join(trackerDir, "index.json"), DEFAULT_INDEX);
222	    await atomicWriteJSON(join(trackerDir, "dependencies.json"), DEFAULT_DEPENDENCIES);
223	    await atomicWriteJSON(join(trackerDir, "users.json"), DEFAULT_USERS);
224	
225	    return { result: "OK", path: resolve(trackerDir) };
226	  }
227	
228	  /**
229	   * Create a new issue.
230	   *
231	   * Generates a unique ID, creates the issue file with creation + update events,
232	   * and inserts an entry into the sorted index. Validates parent constraints if
233	   * `parentId` is provided.
234	   *
235	   * @param params - Creation parameters
236	   * @param params.title - The issue title (required)
237	   * @param params.description - Optional description, defaults to ""
238	   * @param params.status - Initial status, defaults to "idea"
239	   * @param params.priority - Priority 1-5, defaults to 3
240	   * @param params.assignee - Optional assignee, defaults to null
241	   * @param params.tags - Optional tags, defaults to []
242	   * @param params.parentId - Optional parent issue ID for hierarchy
243	   * @param params.author - Override author (resolved by auth layer if not provided)
244	   * @returns `{ id }` on success, or a AgentrackError on auth failure
245	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
246	   * @throws {AgentrackError} NOT_FOUND if parentId doesn't exist in index
247	   * @throws {AgentrackError} HIERARCHY_CONSTRAINT if parent is closed
248	   *
249	   * @example
250	   * ```typescript
251	   * const { id } = await tracker.create({
