24	/**
25	 * Execute a git command synchronously using array-based argument passing.
26	 * Uses execFileSync to avoid shell injection.
27	 */
28	function gitExec(cwd: string, args: string[]): string {
29	  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
30	}
31	
32	/**
33	 * Extract stderr from an execFileSync error.
34	 */
35	function getGitError(err: unknown): string {
36	  if (typeof err === "object" && err !== null && "stderr" in err) {
37	    const stderr = (err as { stderr: unknown }).stderr;
38	    if (typeof stderr === "string") return stderr;
39	  }
40	  return (err as Error).message || String(err);
41	}
42	
43	/**
44	 * Check if `cwd` is inside a git repository.
45	 */
46	function isGitRepo(cwd: string): boolean {
47	  try {
48	    gitExec(cwd, ["rev-parse", "--git-dir"]);
49	    return true;
50	  } catch {
51	    return false;
52	  }
53	}
54	
55	/**
