135	 */
136	function ensureGitignoreEntry(cwd: string): boolean {
137	  const gitignorePath = join(cwd, ".gitignore");
138	  if (existsSync(gitignorePath)) {
139	    const content = readFileSync(gitignorePath, "utf-8");
140	    if (gitignoreHasEntry(content)) {
141	      return false;
