235	/**
236	 * Scenario A: create orphan branch with initial data, push, mount worktree.
237	 * Uses git plumbing commands to avoid modifying the working tree.
238	 */
239	export function initFreshWorktree(cwd: string): WorktreeInitResult {
240	  // 1. Create blob objects for initial files
241	  const configBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`);
242	  const indexBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_INDEX, null, 2)}\n`);
243	  const depsBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_DEPENDENCIES, null, 2)}\n`);
244	  const usersBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_USERS, null, 2)}\n`);
245	
246	  // 2. Create a tree object referencing these blobs
247	  const treeInput = [
248	    `100644 blob ${configBlob}\tconfig.json`,
249	    `100644 blob ${indexBlob}\tindex.json`,
250	    `100644 blob ${depsBlob}\tdependencies.json`,
251	    `100644 blob ${usersBlob}\tusers.json`,
252	  ].join("\n");
253	  const tree = gitMkTree(cwd, treeInput);
254	
255	  // 3. Create a commit from the tree
256	  const commit = gitCommitTree(cwd, tree, "init _agentrack branch");
257	
258	  // 4. Create the _agentrack branch ref
259	  try {
260	    gitExec(cwd, ["branch", WORKTREE_BRANCH, commit]);
261	  } catch (err) {
262	    // Branch might already exist from a failed previous attempt
263	    const stderr = getGitError(err);
264	    if (stderr.includes("already exists")) {
265	      // Force-update the branch to our new commit
266	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, commit]);
267	    } else {
268	      throw new AgentrackError(
269	        ErrorCodes.INVALID_STATE.result,
270	        `Failed to create branch: ${stderr}`,
271	        ErrorCodes.INVALID_STATE.exitCode,
272	      );
273	    }
274	  }
275	
276	  // 5. Push to remote (if available)
277	  if (hasRemote(cwd)) {
278	    try {
279	      gitExec(cwd, ["push", "-u", "origin", WORKTREE_BRANCH]);
280	    } catch (pushErr) {
281	      const stderr = getGitError(pushErr);
282	      // If push fails because branch already exists remotely, fall back to join
283	      if (
284	        stderr.includes("already exists") ||
285	        stderr.includes("failed to push") ||
