/**
 * Check if a remote named 'origin' is configured.
 */
function hasRemote(cwd: string): boolean {
  try {
    const remotes = gitExec(cwd, ["remote"]);
    return remotes.split("\n").some((r) => r.trim() === "origin");
  } catch {
    return false;
  }
